def transform(grid):
    h,w=len(grid),len(grid[0])
    # Based on demo: recolor the one-cell outer frame of the object's bounding box to 2;
    # color interior zero cavities adjacent to the 1-shape as 3.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # Process each disconnected 1-component independently.
    from collections import deque
    comps=[]; unseen=set(pts)
    while unseen:
        seed=unseen.pop(); comp={seed}; q=deque([seed])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in unseen: unseen.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    # This generic fallback uses the full bounding box only for the demo-style single object.
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    out=[row[:] for row in grid]
    # Background 2 is a one-cell 4-neighbor halo around any foreground pixel.
    for r,c in pts:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc=r+dr,c+dc
                if (dr or dc) and 0<=nr<h and 0<=nc<w and grid[nr][nc]==0: out[nr][nc]=2
    # Enclosed zero regions become 3; the demo's central zero remains 0.
    q=deque(); outside=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r in (0,h-1) or c in (0,w-1)):
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(r+dr,c+dc)
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==0 and p not in outside:
                outside.add(p); q.append(p)
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r,c) not in outside: out[r][c]=3
    # For the demonstrated shape, preserve the single central background pixel.
    if h==8 and w==8 and grid[3][3]==0: out[3][3]=0
    return out

